CREATE TABLE IF NOT EXISTS articles (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  content TEXT NOT NULL,
  category TEXT NOT NULL,
  author TEXT NOT NULL,
  date TEXT NOT NULL,
  breaking INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  article_id TEXT NOT NULL,
  name TEXT NOT NULL,
  text TEXT NOT NULL,
  date TEXT NOT NULL
);

INSERT INTO articles (id, title, excerpt, content, category, author, date, breaking) VALUES
('a1', 'Нов езиков модел обещава по-дълга памет в разговорите', 'Разработчиците твърдят, че системата задържа контекст през много по-дълги сесии, без да губи нишката на разговора.', 'Екип от изследователи представи нова архитектура за езикови модели, която според тях удържа контекст в разговори, дълги в пъти повече от досегашните ограничения.

Ключовата промяна е в начина, по който моделът избира кои части от разговора да „запомни“ в компресиран вид, вместо да пази всичко буквално. Това намалява натоварването върху паметта, без потребителят да усеща загуба на детайли.

Първите тестове показват, че моделът се справя добре с дълги технически дискусии и с проекти, разпънати през няколко дни. Предстои независима проверка на резултатите, преди технологията да стигне до масови продукти.', 'ai', 'Ивайло Петров', '2026-08-29', 1),
('a2', 'Тестваме новия сгъваем телефон: къде е компромисът', 'Екранът е впечатляващ, батерията издържа цял ден, но има един детайл, който ще раздели мненията.', 'След две седмици активна употреба, новото сгъваемо устройство остави смесени впечатления. Основният екран е ярък и практически без видима гънка при нормален ъгъл на гледане.

Батерията издържа пълен работен ден при умерена употреба, а камерата се справя добре на дневна светлина. Проблемът е тежината — устройството е осезаемо по-тежко от конкурентните модели, което се усеща след по-дълго държане в ръка.

За хора, които ценят големия екран пред компактността, компромисът си заслужава. За останалите — по-класически флагман остава по-удобен избор.', 'reviews', 'Мария Георгиева', '2026-08-27', 0),
('a3', 'Как да организираш AI инструментите си в едно ежедневие', 'Малка система от три стъпки, с която инструментите спират да се дублират и да ти отнемат време.', 'Повечето хора, които използват няколко AI инструмента едновременно, стигат до объркване — един и същ въпрос се задава на три различни места, а резултатите не се събират никъде.

Първата стъпка е да определиш „основен“ инструмент за писане и „основен“ за проучване — не е нужно да е един и същ. Втората е да пазиш едно общо място (документ или бележник), където преместваш най-добрите резултати, вместо да скачаш между чатове.

Третата стъпка е периодично прочистване — веднъж седмично изтривай разговорите, които вече не ти трябват, за да пазиш фокус върху активните проекти.', 'howto', 'Стефан Колев', '2026-08-25', 0),
('a4', 'Сравнение: два популярни AI асистента за писане на код', 'Единият е по-бърз в кратки задачи, другият държи по-добре контекста на голям проект. Ето разликите на практика.', 'Тествахме двата инструмента върху едни и същи три задачи: рефакторинг на съществуващ модул, писане на нова функционалност от нулата и откриване на грешка в чужд код.

При кратките, изолирани задачи по-бързият инструмент печели осезаемо време. При работа върху по-голям проект обаче другият инструмент показва по-добро разбиране на структурата на кода и предлага по-последователни решения.

Изборът зависи от типа работа — за бързи скриптове единият е по-удобен, за поддръжка на голяма база код другият пести повече нерви на дългосрочен план.', 'comparisons', 'Ивайло Петров', '2026-08-24', 0),
('a5', 'Нов процесор за лаптопи обещава двойна автономност', 'Производителят твърди значителен скок в енергийната ефективност без загуба на производителност.', 'Новото поколение процесори за тънки лаптопи залага на архитектура, при която по-голямата част от ежедневните задачи се обработват от енергийно ефективни ядра, а мощните ядра се включват само при нужда.

Независимо от маркетинговите обещания, реалната автономност зависи силно от софтуерната оптимизация на всеки производител на лаптопи. Първите независими тестове се очакват след официалното пускане на пазара.

Ако резултатите се потвърдят, това би било една от най-съществените стъпки напред от няколко поколения насам.', 'computers', 'Диана Николова', '2026-08-22', 0),
('a6', 'Приложение за фокус събира ред в работния ден', 'Проста идея — един таймер и една задача на екрана — но изпълнението прави разликата.', 'Приложението залага на минимализъм — при отваряне виждаш само текущата задача и таймер, без известия, ленти и допълнителни менюта.

Тестовете ни показват, че липсата на визуален шум наистина помага за по-дълги периоди на концентрация, особено при задачи, изискващи писане или четене.

Не е инструмент за управление на сложни проекти, но за единична дневна фокус сесия върши точно това, за което е замислен.', 'apps', 'Мария Георгиева', '2026-08-20', 0),
('a7', 'AI инструмент за редакция на снимки прескача цяла стъпка от процеса', 'Вместо слоеве и маски, инструментът приема обикновено текстово описание на промяната.', 'Новият инструмент за редакция позволява промени чрез просто описание — например премахване на обект от фона или промяна на осветлението — без нужда от ръчно маркиране на области.

При тестове с портретни снимки резултатите са убедителни в повечето случаи, но при сложни сцени с много обекти инструментът все още прави забележими грешки по краищата.

За бързи корекции спестява време, но за професионална ретуш класическите инструменти засега остават по-предвидими.', 'ai-tools', 'Стефан Колев', '2026-08-18', 0),
('a8', 'Регулаторен орган поставя нови изисквания към AI системи', 'Новите правила засягат прозрачността на данните за обучение на по-големите модели.', 'Новите изисквания задължават компаниите, разработващи по-мащабни модели, да оповестяват общи категории данни, използвани за обучение, без да разкриват търговски тайни.

Реакциите в бранша са смесени — по-малките компании приветстват по-ясните правила, докато част от по-големите играчи предупреждават за административна тежест.

Прилагането на новите изисквания предстои постепенно през следващите месеци, а окончателните насоки все още се уточняват.', 'news', 'Диана Николова', '2026-08-30', 0),
('a9', 'Технологичен гигант обявява преработка на операционната система', 'Фокусът е върху по-бърза навигация и по-дълбока интеграция на AI функции в системата.', 'Компанията представи ранна визия за следващата версия на своята операционна система, като акцентира върху опростена навигация и вградени AI функции на системно ниво, вместо в отделни приложения.

Част от промените са козметични, но по-съществената е новата система за търсене, която според демонстрацията разбира по-сложни, естествено формулирани заявки.

Пълната версия се очаква в началото на следващата година, като част от функциите вероятно ще стигнат първо до по-новите устройства.', 'tech', 'Ивайло Петров', '2026-08-28', 0),
('a10', 'Евтин смартфон изненадва с камера над очакваното', 'В бюджетния сегмент рядко се вижда такъв скок в качеството на снимките при слаба светлина.', 'Тестовете с новия бюджетен модел показаха резултати, необичайни за ценовия сегмент — особено при снимки на закрито и при слабо осветление, където по-евтините устройства обикновено изостават осезаемо.

Екранът и производителността остават на очаквано ниво за цената, без изненади в добра или лоша посока.

За хора, за които камерата е приоритет, но бюджетът е ограничен, това е един от малкото модели тази година, които си заслужават разглеждане.', 'mobile', 'Мария Георгиева', '2026-08-26', 0);
